const chunkSize = Math.ceil(faceArr.length / 30);
let chunks = splitArray(faceArr, chunkSize);
let custom = "无";
let colorOptions = [];
let faceOptions = [];

function start() {
    status = -1;
    action(1, 0, 0);
}

function action(mode, type, selection) {
    if (mode === -1 || (mode === 0 && type > 0)) {
        cm.dispose();
        return;
    }

    updateStatus(mode);

    if (status === 0) {
        let msg = "本服共有 " + faceArr.length + " 组脸型（" + allFaceArr.length + " 个）\r\n\r\n"
        msg += "#L0##r换瞳色#b#l\r\n"
        msg += "#L1000##r随机脸型（原始瞳色）#b#l\r\n"
        msg += "#L1001##r随机脸型（随机瞳色）#b#l\r\n"
        for (let i = 1; i <= 30; i++) {
            msg += "#L" + i + "#换脸型" + i + " (" + getDataByIndex(chunks, i).length + "款)#l\r\n";
        }
        cm.sendSimple(msg);
    } else if (status === 1) {
        if (selection === 0) {
            let curFace = cm.getPlayer().getFace();
            colorOptions = getFaceColorOptions(curFace);
            custom = "颜色"
            cm.sendStyle("慢慢挑", colorOptions);
        } else if (selection === 1000) {
            cm.setFace(faceArr[Math.floor(Math.random() * faceArr.length)]);
            cm.sendOk("换好了");
            cm.dispose();
        } else if (selection === 1001) {
            cm.setFace(allFaceArr[Math.floor(Math.random() * allFaceArr.length)]);
            cm.sendOk("换好了");
            cm.dispose();
        } else {
            faceOptions = getDataByIndex(chunks, selection);
            custom = "脸型"
            cm.sendStyle("慢慢挑", faceOptions);
        }
    } else if (status === 2) {
        if (custom === "颜色") {
            cm.setFace(colorOptions[selection]);
        } else if (custom === "脸型") {
            cm.setFace(faceOptions[selection]);
        }
        cm.sendOk("换好了");
        cm.dispose();
    }
}

function updateStatus(mode) {
    if (mode === 1) {
        status++;
    } else {
        status--;
    }
}

function splitArray(arr, chunkSize) {
    const result = [];
    for (let i = 0; i < arr.length; i += chunkSize) {
        result.push(arr.slice(i, i + chunkSize));
    }
    return result;
}

function getDataByIndex(chunks, index) {
    return chunks[index - 1];
}

function getFaceColorOptions(face) {
    let result = [];
    allFaceArr.forEach(f => {
        if (isSameFace(f, face)) result.push(f);
    })
    return result;
}

function isSameFace(face1, face2) {
    if (Math.floor(face1 / 1000) !== Math.floor(face2 / 1000)) return false;
    if (face1 % 100 !== face2 % 100) return false;
    return true;
}